    // Combine these to get:
    assert forall |i: NodeId| i < pre.num_replicas implies
        pre.local_versions[i] <= pre.tail by {
        assert(pre.local_versions.contains_key(i));
        assert(pre.head <= pre.local_versions[i] <= pre.tail);
    }

    // Now, min_local_version is computed as the minimum over all local_versions
    // More specifically, min_local_version = min({pre.local_versions[i] | i < pre.num_replicas})
